  async function start(chapter='CH00',mode='story'){cancelSceneLoad();interactionContinuation=null;closeModal(false);mix.stopAll();transitionBusy=false;clearTimeout(transitionTimer);renderedLineKey=null;renderedScene=null;autoViewKey=null;state=E.create(D,chapter,mode);E.record(D,state);scenePlayed.clear();mix.voiceKey=null;mix.currentLine=null;screen='game';saveCurrent();if(!await game())return;}
  function resume(which){cancelSceneLoad();interactionContinuation=null;const restored=E.restore(D,store[which]);if(!restored){toast('Сохранение недоступно. Можно начать любую главу.');return;}closeModal(false);mix.stopAll();transitionBusy=false;clearTimeout(transitionTimer);renderedLineKey=null;renderedScene=null;autoViewKey=null;state=restored;screen='game';scenePlayed.add(state.sceneId);mix.voiceKey=null;mix.currentLine=null;if(!continueInteraction())game();}
