  function chapterCards(){const done=new Set([...(store.story?.completedChapters||[]),...store.records.map(r=>r.chapterId)]);return `<p class="muted">Все главы доступны сразу. Отдельный запуск не меняет основную историю.</p><div class="chapter-grid">${D.chapters.map((c,i)=>`<button class="chapter-card" data-action="chapter" data-value="${c.id}"><img src="${art[c.bg]}" alt="" loading="lazy"><span class="chapter-tint"></span><span class="chapter-index">${String(i).padStart(2,'0')}</span><span class="chapter-card-content"><span class="eyebrow">${esc(c.eyebrow)}</span><strong>${esc(c.title)}</strong><span>${esc(c.theme)}</span><small>${c.minutes} <i>·</i> ${done.has(c.id)?'Пройдена · есть другие решения':'Не пройдена'}</small></span>${icon('arrow')}</button>`).join('')}</div>`;}

  function bubble(role,text,own=false){return `<div class="chat-message ${own?'own':''}">${role&&!own?`<span class="chat-author" data-speaker="${esc(role)}">${esc(names[role]||role)}</span>`:''}<p>${esc(text)}</p><small>${state?.sceneId.startsWith('C3')?'15:42':'19:42'}${own?' ✓✓':''}</small></div>`;}
  function voiceBubble(id){const a=tracks[id];return `<div class="voice-message"><div class="voice-controls"><button class="voice-play" data-voice="${id}" aria-label="Воспроизвести голосовое сообщение" aria-pressed="false">${icon('play')}</button><div class="waveform" data-audio-progress="${id}" role="progressbar" aria-label="Воспроизведение голосового сообщения" aria-valuemin="0" aria-valuemax="${Math.ceil(a.duration)}" aria-valuenow="0">${Array.from({length:25},(_,i)=>`<i style="--h:${10+(i*17%30)}px"></i>`).join('')}</div><span class="audio-time" data-audio-time="${id}">${formatTime(a.duration)}</span></div><details><summary>Расшифровка</summary><p>${esc(a.transcript)}</p><button data-action="voiceRead" data-value="${id}">Прочитано ${icon('check')}</button></details></div>`;}
  function phoneFrame(title,role,content,subtitle='мессенджер',actions='',call=false){return `<aside class="phone-panel ${call?'call-phone':''}" aria-label="Игровой телефон"><div class="phone-case"><div class="phone-status"><span>${esc(D.scenes[state.sceneId].time.match(/\d\d:\d\d/)?.[0]||'12:00')}</span><span class="phone-notch"></span><span>▥ ▰</span></div><div class="phone-header">${avatar(role)}<button class="phone-contact" data-action="profile" data-value="${role||'unknown'}"><strong>${esc(title)}</strong><small>${esc(subtitle)}</small></button><span class="phone-dots" aria-hidden="true">•••</span></div><div class="phone-scroll" tabindex="0" aria-label="Содержимое телефона">${content}</div>${taskHint()}${actions?`<div class="phone-tools">${actions}</div>`:''}<div class="phone-bottom"><span></span></div></div></aside>`;}
  function feedContent(kind){return `<div class="feed-heading"><span>Лента</span><small>Для вас</small></div>`+window.NOVEL_ASSETS.feeds.filter(f=>f.feed===kind).map(f=>`<article class="feed-post" data-action="post" data-value="${f.id}"><div class="feed-author">${f.avatarCharacter?avatar(f.avatarCharacter):'<span class="feed-letter">'+esc(f.initials||f.author[0])+'</span>'}<div><strong>${esc(f.author)}</strong><small>сегодня · ${f.kind==='suspicious'?'объявление':'публикация'}</small></div></div>${f.title?`<h3>${esc(f.title)}</h3>`:''}<p>${esc(f.body)}</p>${f.image?`<img src="assets/${esc(f.image)}" alt="${esc(f.title||f.body)}" loading="eager" decoding="sync">`:''}<button class="post-button" data-action="post" data-value="${f.id}">${state.seenPosts.includes(f.id)?'Прочитано':'Посмотреть'} ${icon('arrow')}</button></article>`).join('')+'<p class="feed-end">Конец ленты</p>';}
  function tablePreview(){return `<div class="attachment"><div class="file-icon">XLS</div><strong>Контакты группы</strong><small>Доступ для сверки</small></div><div class="data-preview"><table><caption>Контакты и распределение на практику</caption><thead><tr><th>Имя</th><th>Телефон</th><th>Практика</th></tr></thead><tbody><tr><td>Даша Л.</td><td>+375 •• ••• •• ••</td><td>Согласовано</td></tr><tr><td>Максим К.</td><td>+375 •• ••• •• ••</td><td>Уточнить</td></tr><tr><td>Кристина В.</td><td>+375 •• ••• •• ••</td><td>Согласовано</td></tr></tbody></table></div>`;}
