    const canChoose=last&&scene.choices&&!task&&!waitingMessage(),phoneChoice=!!P.callDecision(D,state);
    const present=[];ls.slice(0,state.lineIndex+(waitingMessage()?0:1)).forEach(l=>{if(scene.phone==='wake'&&['mother','father'].includes(l.speaker))return;if(V.characters[l.speaker]&&l.speaker!=='petya'){const previous=present.findIndex(x=>x.role===l.speaker);if(previous>=0)present.splice(previous,1);present.push({role:l.speaker,emotion:l.emotion});}});
